def truthOr(f: Formula, otherwise: Boolean): Boolean =
  Arithmetic.truth(f) match {
    case Some(true) => true
    case Some(false) => false
    case None => otherwise
  }

def isLinear(t: Term): Boolean = t match {
  case Term.Int(_) => true
  case Term.Dec(_) => true
  case _ => false
}

def intKey(n: BigInt): String = n match {
  case n if n == 0 => "0"
  case n if n < 0 => s"${n.abs.key}(-)"
  case _ => s"(${n})"
}

def fieldOf(text: String, k: String): Option[Json] = {
  Json.parse(text).toOption.flatMap { json =>
    json.get(k).toOption
  }
}

def textAt(doc: Json, path: List[String]): Option[String] = {
  def getJsonValue(json: Json, path: List[String]): Option[Json] = path match {
    case Nil => Some(json)
    case head :: rest =>
      json match {
        case Json.Obj(map) => map.get(head).flatMap(getJsonValue(_, rest))
        case Json.Array(arr) => if (rest.isEmpty) Some(arr.headOption.map(_.toString)) else arr.get(rest.head).flatMap(getJsonValue(_, rest.drop(1)))
        case _ => None
      }
  }
  getJsonValue(doc, path).flatMap { json =>
    json match {
      case Json.Str(s) => Some(s)
      case _ => None
    }
  }
}

def present(doc: Json, path: List[String]): Boolean = {
  def find(json: Json, path: List[String]): Option[Json] = path match {
    case Nil => Some(json)
    case head :: rest =>
      json match {
        case Json.Obj(m) => m.get(head).flatMap(find(_, rest))
        case Json.Array(a) => if (rest.isEmpty) Some(a.headOption.getOrElse(Json.Null)) else a.findIndex(_ => find(_, rest)).map(Json.Obj(_).getOrElse(Json.Null))
        case _ => None
      }
  }
  find(doc, path).filterNot(_.isNull).isDefined
}

def keyLength(n: Long): Int = {
  val key = Data.key(n)
  if (key.length == 12) key.length else 12
}

def bothPaths(path: List[String]): (String, String) = {
  val jsonPath = Dialect.jsonPath(path)
  val pgJsonPath = Dialect.pgJsonPath(path)
  (jsonPath, pgJsonPath)
}

def quotedOrNone(name: String): Option[String] = {
  Dialect.quoted(name) match {
    case Some(s) => Some(s)
    case None => None
  }
}

import scala.quoted.*
import okapi.Json.*
import okapi.Json.Null
import okapi.SqlData._

def docOrNull(text: String): Json =
  try {
    SqlData.doc(text)
  } catch {
    case e: Exception => Null
  }

def tableOfNamed(collection: String): Option[String] = {
  Data.named(collection).flatMap { name =>
    SqlData.tableOf(collection).toOption
  }
}

def outermost(symbol: String): Option[String] = {
  val parts = symbol.split('/').filter(_.nonEmpty)
  parts.headOption
}

def foundWhere(out: String): Option[String] = Equivalence.verdict(out).flatMap {
  case Right(Verdict.NotEquivalent(found, _)) => Some(found)
  case _ => None
}

def firstRefused(commands: List[String]): Option[String] = {
  commands.find { command =>
    !Hook.allowed(command)
  }.getOrElse(None)
}

def hexPrefix(text: String, n: Int): String = {
  val hash = Sha256.hex(text)
  if (n <= 0) ""
  else hash.take(n)
}

def fieldOf(text: String, k: String): Option[Json] = {
  val json = Json.parse(text).toOption.get
  json.get(k).toOption
}

